package com.adib.maintenance;
import android.app.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.shadows.ShadowAlertDialog;import java.util.*;import java.time.Duration;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={28,35},manifest=Config.NONE)
public class WorkAssigneeDialogTest {
 Activity a;JSONObject task,actor;List<String> requests;TaskReminderActions.Transport old;
 @Before public void before()throws Exception{a=Robolectric.buildActivity(Activity.class).setup().get();task=new JSONObject().put("id","t").put("sourceKey","todo").put("tapsirildi",new JSONArray().put("Huseyn"));actor=new JSONObject().put("assignee","Huseyn");AccountSession.editable=true;DirectConfig.current="test";requests=Collections.synchronizedList(new ArrayList<>());old=WorkTimerClient.transport;WorkTimerClient.transport=(method,path,body)->{requests.add(method+" "+path);if(path.startsWith("/api/task-options"))return new JSONObject().put("todo",new JSONObject().put("tapsirildi",new JSONObject().put("options",new JSONArray().put("Huseyn").put("Araz").put("Ilqar"))));if(method.equals("PATCH"))return new JSONObject().put("ok",true);return new JSONObject();};WorkTimerClient.assignmentEditors.clear();}
 @After public void after(){WorkTimerClient.transport=old;AccountSession.editable=true;WorkTimerClient.assignmentEditors.clear();a.finish();}
 void idle(){Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(180));}
 void await(java.util.function.BooleanSupplier condition)throws Exception{for(int i=0;i<100;i++){idle();if(condition.getAsBoolean())return;Thread.sleep(15);}fail("Async timeout");}
 AlertDialog chooser(){WorkTimerClient.showWorkerChoice(a,task,actor,"");idle();return ShadowAlertDialog.getLatestAlertDialog();}
 AlertDialog editor(AlertDialog chooser)throws Exception{chooser.findViewById(android.R.id.content).findViewWithTag("work-change-assignees").performClick();AlertDialog d=ShadowAlertDialog.getLatestAlertDialog();await(()->d.getButton(-1).isEnabled());return d;}
 CheckBox check(View v,String name){if(v instanceof CheckBox&&((CheckBox)v).getText().toString().equals(name))return (CheckBox)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){CheckBox found=check(((ViewGroup)v).getChildAt(i),name);if(found!=null)return found;}return null;}
 @Test public void saveReturnsToChoiceWithoutStarting()throws Exception{AlertDialog original=chooser(),d=editor(original);check(d.getWindow().getDecorView(),"Araz").performClick();d.getButton(-1).performClick();await(()->!d.isShowing());AlertDialog next=ShadowAlertDialog.getLatestAlertDialog();Spinner pick=next.getWindow().getDecorView().findViewWithTag("work-start-worker");assertEquals(2,pick.getCount());assertEquals("Huseyn",pick.getSelectedItem());assertEquals(2,task.getJSONArray("tapsirildi").length());assertFalse(requests.stream().anyMatch(p->p.contains("work-timer")));assertEquals(1,requests.stream().filter(p->p.equals("PATCH /api/task")).count());}
 @Test public void cancelDoesNotChangeAssignments()throws Exception{AlertDialog original=chooser(),d=editor(original);check(d.getWindow().getDecorView(),"Araz").performClick();d.getButton(-2).performClick();assertTrue(original.isShowing());assertEquals(1,task.getJSONArray("tapsirildi").length());assertFalse(requests.stream().anyMatch(p->p.startsWith("PATCH")));}
 @Test public void filterPreservesSelections()throws Exception{AlertDialog d=editor(chooser());check(d.getWindow().getDecorView(),"Araz").performClick();EditText search=d.getWindow().getDecorView().findViewWithTag("work-assignee-search");search.setText("Ilq");assertNull(check(d.getWindow().getDecorView(),"Huseyn"));search.setText("");assertTrue(check(d.getWindow().getDecorView(),"Huseyn").isChecked());assertTrue(check(d.getWindow().getDecorView(),"Araz").isChecked());d.getButton(-2).performClick();}
 @Test public void emptyAssignmentCannotStartButCanBeEdited()throws Exception{task.put("tapsirildi",new JSONArray());AlertDialog c=chooser();assertFalse(c.getButton(-1).isEnabled());AlertDialog d=editor(c);d.getButton(-1).performClick();assertTrue(d.isShowing());assertFalse(requests.stream().anyMatch(p->p.startsWith("PATCH")));check(d.getWindow().getDecorView(),"Araz").performClick();d.getButton(-1).performClick();await(()->!d.isShowing());assertEquals("Araz",task.getJSONArray("tapsirildi").getString(0));}
 @Test public void permissionIsNotBypassed()throws Exception{AccountSession.editable=false;AlertDialog c=chooser();assertFalse(c.getWindow().getDecorView().findViewWithTag("work-change-assignees").isEnabled());final JSONObject[] result={new JSONObject()};WorkTimerClient.saveAssignments(a,task,new JSONArray().put("Araz"),(r,e)->result[0]=r);assertNull(result[0]);assertTrue(requests.isEmpty());}
 @Test public void serverFailureKeepsEditorAndAssignment()throws Exception{AlertDialog d=editor(chooser());check(d.getWindow().getDecorView(),"Araz").performClick();WorkTimerClient.transport=(m,p,b)->{throw new Exception("Access denied");};d.getButton(-1).performClick();await(()->d.getButton(-1).isEnabled());assertTrue(d.isShowing());assertTrue(check(d.getWindow().getDecorView(),"Araz").isChecked());assertEquals(1,task.getJSONArray("tapsirildi").length());d.getButton(-2).performClick();}
 @Test public void boundEditorUsesItsAutosaveAndUpdatesField()throws Exception{EditText field=new EditText(a);field.setText("Huseyn");TextView status=new TextView(a);final int[] writes={0};TaskAutosave saver=new TaskAutosave(a,"/api/task","t",false,()->new JSONObject().put("id","t").put("sourceKey","todo").put("tapsirildi",new JSONArray(Arrays.asList(field.getText().toString().split(", ")))),(m,p,b)->{writes[0]++;return new JSONObject().put("id","t");},(b,r,c)->{},status);saver.watch(field);WorkTimerClient.bindAssignmentEditor(task,field,saver);final boolean[] done={false};WorkTimerClient.saveAssignments(a,task,new JSONArray().put("Huseyn").put("Araz"),(r,e)->{assertNotNull(r);done[0]=true;});await(()->done[0]);assertEquals("Huseyn, Araz",field.getText().toString());assertEquals(2,task.getJSONArray("tapsirildi").length());assertEquals(1,writes[0]);assertTrue(requests.isEmpty());WorkTimerClient.unbindAssignmentEditor(task);saver.detach();}
 @Test public void selectionModelPreservesUnknownExistingNames(){WorkAssigneeSelection m=new WorkAssigneeSelection(Arrays.asList("Araz","Araz",""),Arrays.asList("Huseyn"));assertEquals(Arrays.asList("Araz","Huseyn"),m.options);assertEquals(Arrays.asList("Huseyn"),m.values());m.choose("Araz",true);assertEquals(Arrays.asList("Araz"),m.visible("ARA"));assertEquals(Arrays.asList("Huseyn","Araz"),m.values());}
}
